(342715, 26818, 7543, '<td valign="top">The frame is a bit to heavy for my taste.</td>', 'The frame is a bit to heavy for my taste.', '2003-06-30 13:30:50.000000', NULL, 1),
(342720, 26452, 6202, '<td valign="top">This is a very stunning B&amp;W nicely done.  I love it, and this one is simply cropped so perrectly, the clouds are there but not over dominating the image, the waves are present, and overall it just is so appealling,   iBest of luck cause it is my favorite of the week.  10</td>', 'This is a very stunning B&W nicely done.  I love it, and this one is simply cropped so perrectly, the clouds are there but not over dominating the image, the waves are present, and overall it just is so appealling,   iBest of luck cause it is my favorite of the week.  10', '2003-06-30 13:43:02.000000', NULL, 1),
(342722, 26299, 327, '<td valign="top">Pretty good shot except I''m not crazy for the crop. I believe you''ve tried to include too much. I''m guilty of the same thing...(often). The large balloon is cropped too tight and the sun flare really doesn''t add to the over all shot.<br/>Still this is not a disaster .....</td>', 'Pretty good shot except I''m not crazy for the crop. I believe you''ve tried to include too much. I''m guilty of the same thing...(often). The large balloon is cropped too tight and the sun flare really doesn''t add to the over all shot.Still this is not a disaster .....', '2003-06-30 13:44:51.000000', NULL, 1),
(342725, 26391, 327, '<td valign="top">Small shot, yes but that doesn''t really bother me as much as the fuzzy focus. The colors are very nice. I believe you''ve just focused on the wrong area of interest.</td>', 'Small shot, yes but that doesn''t really bother me as much as the fuzzy focus. The colors are very nice. I believe you''ve just focused on the wrong area of interest.', '2003-06-30 13:45:49.000000', NULL, 1),
(342726, 26912, 6202, '<td valign="top">Very nicely done, b &amp; w is so perfect for this image, works wonderfully, couldn''t image it having any impact in color like it does in B &amp; W.</td>', 'Very nicely done, b & w is so perfect for this image, works wonderfully, couldn''t image it having any impact in color like it does in B & W.', '2003-06-30 13:46:05.000000', NULL, 1),
(342727, 26835, 327, '<td valign="top">Very pretty but this is very busy and a bit dark. I like this and I''m sure it wasn''t easy to shoot. Great color.</td>', 'Very pretty but this is very busy and a bit dark. I like this and I''m sure it wasn''t easy to shoot. Great color.', '2003-06-30 13:47:34.000000', NULL, 1),
(342728, 26883, 327, '<td valign="top">Not crazy for the hand, finger or what ever that is behind the flower. Sorry, but this doesn''t work for me.</td>', 'Not crazy for the hand, finger or what ever that is behind the flower. Sorry, but this doesn''t work for me.', '2003-06-30 13:48:41.000000', NULL, 1),
