(343090, 26376, 4810, '<td valign="top">Very well done</td>', 'Very well done', '2003-06-30 19:27:21.000000', NULL, 1),
(343091, 26077, 2152, '<td valign="top">Well composed, but there isn''t much interesting material here.  No people, no waves, no animals, not much color, the light isn''t anything special.  I do like the 2 triangle shapes formed by the water and land.  I hope I''m not being too harsh, but this shot had some potential with its composition - the way it is, it''s pretty bland.  You might want to try during sunrise/sunset.  Yeah, it''s cliche, but you''ll get great light and color.</td>', 'Well composed, but there isn''t much interesting material here.  No people, no waves, no animals, not much color, the light isn''t anything special.  I do like the 2 triangle shapes formed by the water and land.  I hope I''m not being too harsh, but this shot had some potential with its composition - the way it is, it''s pretty bland.  You might want to try during sunrise/sunset.  Yeah, it''s cliche, but you''ll get great light and color.', '2003-06-30 19:29:34.000000', NULL, 1),
(343093, 26731, 7763, '<td valign="top">I think some of the top of this photo could be cropped, the light drawers your eye away from whats happening here</td>', 'I think some of the top of this photo could be cropped, the light drawers your eye away from whats happening here', '2003-06-30 19:30:14.000000', NULL, 1),
