INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(343184, 26817, 200, '<td valign="top">hope you didnt get stung! Great image</td>', 'hope you didnt get stung! Great image', '2003-06-30 21:03:01.000000', NULL, 1),
(343185, 26413, 200, '<td valign="top">very prett and nice lighting</td>', 'very prett and nice lighting', '2003-06-30 21:03:43.000000', NULL, 1),
(343186, 26268, 5007, '<td valign="top">The bug looks a little on the dead side. Interesting colors though.</td>', 'The bug looks a little on the dead side. Interesting colors though.', '2003-06-30 21:03:47.000000', NULL, 1),
(343187, 26949, 714, '<td valign="top">Wicked shot...this really plays tricks on the eyes.</td>', 'Wicked shot...this really plays tricks on the eyes.', '2003-06-30 21:03:56.000000', NULL, 1),
(343188, 26924, 200, '<td valign="top">I want to steal this one when i do a wedding! very nice</td>', 'I want to steal this one when i do a wedding! very nice', '2003-06-30 21:04:18.000000', NULL, 1),
(343190, 26947, 200, '<td valign="top">he''s beautiful...beautiful baby brother perhaps...good job</td>', 'he''s beautiful...beautiful baby brother perhaps...good job', '2003-06-30 21:05:09.000000', NULL, 1),
(343191, 26913, 200, '<td valign="top">I like this perspective. good job</td>', 'I like this perspective. good job', '2003-06-30 21:06:07.000000', NULL, 1),
(343192, 26884, 200, '<td valign="top">Yikes! beautiful resolution and clarity</td>', 'Yikes! beautiful resolution and clarity', '2003-06-30 21:06:56.000000', NULL, 1),
(343193, 26922, 2152, '<td valign="top">Hey - I''ve been on this ship before, not on a cruise though - to interview Brooke Burke and Miss America who were there for the ship''s christeining (lucky me).  The composition is good.  I like how the triangles on the bridge contrast with the squares on the ship.  Would like to see more color though...</td>', 'Hey - I''ve been on this ship before, not on a cruise though - to interview Brooke Burke and Miss America who were there for the ship''s christeining (lucky me).  The composition is good.  I like how the triangles on the bridge contrast with the squares on the ship.  Would like to see more color though...', '2003-06-30 21:08:06.000000', NULL, 1),
(343194, 26914, 714, '<td valign="top">And where did you say you lived! ;-)  Great shot!!</td>', 'And where did you say you lived! ;-)  Great shot!!', '2003-06-30 21:09:07.000000', NULL, 1),
(343195, 26817, 1368, '<td valign="top">This is sooo cool! Great picture! good luck  ;) perfect 10 if I could vote</td>', 'This is sooo cool! Great picture! good luck  ;) perfect 10 if I could vote', '2003-06-30 21:09:19.000000', NULL, 1),
(343196, 26940, 200, '<td valign="top">very beautiful</td>', 'very beautiful', '2003-06-30 21:09:46.000000', NULL, 1),
(343197, 26341, 200, '<td valign="top">very cute...great job</td>', 'very cute...great job', '2003-06-30 21:11:18.000000', NULL, 1),
(343198, 26828, 714, '<td valign="top">She is the cutest!!  Great shot.  I love her hair...This might also look good in black and white.  Good luck. Vote 10</td>', 'She is the cutest!!  Great shot.  I love her hair...This might also look good in black and white.  Good luck. Vote 10', '2003-06-30 21:11:37.000000', NULL, 1),
(343199, 26775, 200, '<td valign="top">clever clever...good job</td>', 'clever clever...good job', '2003-06-30 21:11:56.000000', NULL, 1),
(343200, 26442, 714, '<td valign="top">Very nice background with the beautiful color of the flowers.</td>', 'Very nice background with the beautiful color of the flowers.', '2003-06-30 21:12:08.000000', NULL, 1),
(343201, 26683, 2152, '<td valign="top">Nice composition, but I''d like to see that reflection disappear.  It takes away from what otherwise would be a very professional type shot.  Might consider a little unsharp mask, as well.</td>', 'Nice composition, but I''d like to see that reflection disappear.  It takes away from what otherwise would be a very professional type shot.  Might consider a little unsharp mask, as well.', '2003-06-30 21:12:22.000000', NULL, 1),
(343202, 26832, 6630, '<td valign="top">This is so cute!!!</td>', 'This is so cute!!!', '2003-06-30 21:15:27.000000', NULL, 1),
(343203, 26277, 200, '<td valign="top">Looks like he''s posing for you.  I can even see a faint smile :) Great capture</td>', 'Looks like he''s posing for you.  I can even see a faint smile :) Great capture', '2003-06-30 21:15:29.000000', NULL, 1),
(343204, 26268, 200, '<td valign="top">Very impressive. I love the red wings! Is the bug dead?</td>', 'Very impressive. I love the red wings! Is the bug dead?', '2003-06-30 21:17:04.000000', NULL, 1),
(343207, 26289, 2152, '<td valign="top">Nice job with the white on white.  There are reflections on the bowls, but nothing major.  I do see a corner about 1/3 the way up that you might be able to eliminate with levels adjustments.  But this is a tough one to pull off and you did it well.</td>', 'Nice job with the white on white.  There are reflections on the bowls, but nothing major.  I do see a corner about 1/3 the way up that you might be able to eliminate with levels adjustments.  But this is a tough one to pull off and you did it well.', '2003-06-30 21:27:06.000000', NULL, 1),
(343209, 26739, 2152, '<td valign="top">The color in the hair and dress are great and provide nice contrast with the background.  Good expression, too.  I think the composition could be better though.  It seems there''s a lot of empty space that could be eliminated with a tighter crop.</td>', 'The color in the hair and dress are great and provide nice contrast with the background.  Good expression, too.  I think the composition could be better though.  It seems there''s a lot of empty space that could be eliminated with a tighter crop.', '2003-06-30 21:41:49.000000', NULL, 1),
(343211, 26722, 2152, '<td valign="top">Well composed, but the boat is a little too far to the right for my taste.  It''s also slightly soft - might want to consider a little unsharp mask.</td>', 'Well composed, but the boat is a little too far to the right for my taste.  It''s also slightly soft - might want to consider a little unsharp mask.', '2003-06-30 21:50:21.000000', NULL, 1),
(343212, 26779, 2152, '<td valign="top">Nice texture and I like the negative space idea.  The bark on the lower right is a little overexposed, but I''m not sure there''s anything you can do about that.  I think I''d like to see the whole bug rather than the bottom cut off.</td>', 'Nice texture and I like the negative space idea.  The bark on the lower right is a little overexposed, but I''m not sure there''s anything you can do about that.  I think I''d like to see the whole bug rather than the bottom cut off.', '2003-06-30 21:52:56.000000', NULL, 1),
(343214, 26896, 2152, '<td valign="top">Great action shot and dof.  Nice job with the framing, too.</td>', 'Great action shot and dof.  Nice job with the framing, too.', '2003-06-30 22:02:28.000000', NULL, 1),
(343215, 26880, 2152, '<td valign="top">Nice high-contrast shot.  I like how the edge on the left and the cutout are a little uneven - makes it more interesting than a perfect "B."</td>', 'Nice high-contrast shot.  I like how the edge on the left and the cutout are a little uneven - makes it more interesting than a perfect "B."', '2003-06-30 22:07:26.000000', NULL, 1),
(343216, 26866, 1041, '<td valign="top">Challenge met.  I think you were going for the "desaturate all but one color" thing here, I''m not sure it works for me though.  <br/>IT makes the flowers stand out more, but the bees are almost fading into the background because of it.  The image also looks as if it needs rotating 90 degrees CW and could be a little bigger.  On the plus side, I think you have a good base image to work with, try and work in color and make it a little bigger and see what you get :)</td>', 'Challenge met.  I think you were going for the "desaturate all but one color" thing here, I''m not sure it works for me though.  IT makes the flowers stand out more, but the bees are almost fading into the background because of it.  The image also looks as if it needs rotating 90 degrees CW and could be a little bigger.  On the plus side, I think you have a good base image to work with, try and work in color and make it a little bigger and see what you get :)', '2003-06-30 22:09:13.000000', NULL, 1),
(343220, 26268, 1041, '<td valign="top">So, despite this being a bug &amp; bloom shot, you''ve made it into my top 5 ;)  Actually, I''ve been known to like bugs &amp; blooms.  You met the challenge (twice).  I love that you''ve only included a quarter of the flower, that the white petals blur a bit towards the background and that your bug has red wings to match the flower!!!  Plus, the sharpness and focus is tack-on.  Border and background both compliment the shot nicely.  Nothing I would change, a shot I would''ve been proud to take.  :)</td>', 'So, despite this being a bug & bloom shot, you''ve made it into my top 5 ;)  Actually, I''ve been known to like bugs & blooms.  You met the challenge (twice).  I love that you''ve only included a quarter of the flower, that the white petals blur a bit towards the background and that your bug has red wings to match the flower!!!  Plus, the sharpness and focus is tack-on.  Border and background both compliment the shot nicely.  Nothing I would change, a shot I would''ve been proud to take.  :)', '2003-06-30 22:12:47.000000', NULL, 1),
(343222, 26858, 4536, '<td valign="top">Wow, that''s a lot of green, maybe too much. Looks like they are on their way to get wet, Niagra falls? Nice composition.</td>', 'Wow, that''s a lot of green, maybe too much. Looks like they are on their way to get wet, Niagra falls? Nice composition.', '2003-06-30 22:13:59.000000', NULL, 1),
(343223, 26950, 1041, '<td valign="top">Hm.  I''m a bit undecided about your submission.  I guess it meets the challenge on a thematic basis.  Personally, I''m rarely a fan of "digital art" vs photography, although that has been known to happen on occasion.  Overall, I don''t think you''ve quite achieved that for me, but I''m not sure how to put it into words.  I might come back if I think about it more...</td>', 'Hm.  I''m a bit undecided about your submission.  I guess it meets the challenge on a thematic basis.  Personally, I''m rarely a fan of "digital art" vs photography, although that has been known to happen on occasion.  Overall, I don''t think you''ve quite achieved that for me, but I''m not sure how to put it into words.  I might come back if I think about it more...', '2003-06-30 22:14:59.000000', NULL, 1),
(343224, 26775, 7556, '<td valign="top">Now that''s a good idea, very creative...I like the dark contrast, good detail &amp; composition, good colors too...</td>', 'Now that''s a good idea, very creative...I like the dark contrast, good detail & composition, good colors too...', '2003-06-30 22:16:16.000000', NULL, 1),
(343225, 26816, 1041, '<td valign="top">Plenty of "B"s in your shot, so you definitely meet the challenge.  From a photographic point of view, while you probably had to take the opportunity and take the shot fast (unless you encouraged the kids to read like that), there are many things to look out for that might make for a better photo.  The reflection of the flash, cutting off the kid''s legs and taking the photo from your eye-level rather than theirs are the biggest ones to me.  Try take the pic from their level and somewhat from the side (or without the flash) to see the difference.  With all that said and done, they are very cute on how they are picking and reading their books, definitely a keeper for the family album.</td>', 'Plenty of "B"s in your shot, so you definitely meet the challenge.  From a photographic point of view, while you probably had to take the opportunity and take the shot fast (unless you encouraged the kids to read like that), there are many things to look out for that might make for a better photo.  The reflection of the flash, cutting off the kid''s legs and taking the photo from your eye-level rather than theirs are the biggest ones to me.  Try take the pic from their level and somewhat from the side (or without the flash) to see the difference.  With all that said and done, they are very cute on how they are picking and reading their books, definitely a keeper for the family album.', '2003-06-30 22:17:36.000000', NULL, 1),
(343226, 26834, 4536, '<td valign="top">Nice catch. A couple of suggestions, #1 needs more contrast, a bit too grey. #2 crop in on both sides  to get rid of the man made fencing, would look more natural that way (2 inches on left, 1 on the right).</td>', 'Nice catch. A couple of suggestions, #1 needs more contrast, a bit too grey. #2 crop in on both sides  to get rid of the man made fencing, would look more natural that way (2 inches on left, 1 on the right).', '2003-06-30 22:18:43.000000', NULL, 1),
(343227, 26766, 1041, '<td valign="top">Well, you''ve already commented on "doing the out of the ordinary" thing and converting to negative.  While you meet the challenge (bug), as a photo, it is not so appealing to me.  I love macro and close-up photography, but I mostly like it looking natural.  Also, I would''ve never recognized a finger here if you hadn''t said so.  On the plus side, I think you have a much more interesting original to work from and not converting to negative would be a big improvement in my mind.  After all, it''s always cool to catch those bugs on "film", you see so much more of them then you see in real life. :)</td>', 'Well, you''ve already commented on "doing the out of the ordinary" thing and converting to negative.  While you meet the challenge (bug), as a photo, it is not so appealing to me.  I love macro and close-up photography, but I mostly like it looking natural.  Also, I would''ve never recognized a finger here if you hadn''t said so.  On the plus side, I think you have a much more interesting original to work from and not converting to negative would be a big improvement in my mind.  After all, it''s always cool to catch those bugs on "film", you see so much more of them then you see in real life. :)', '2003-06-30 22:20:25.000000', NULL, 1),
(343229, 26947, 4536, '<td valign="top">Beautiful portrait except for the softness in his eyes, eyes need to be tack sharp. Also cropping a bit on the left to leave more room in front of him would help the composition.</td>', 'Beautiful portrait except for the softness in his eyes, eyes need to be tack sharp. Also cropping a bit on the left to leave more room in front of him would help the composition.', '2003-06-30 22:24:33.000000', NULL, 1),
(343230, 26117, 1041, '<td valign="top">Yep, you met the challenge here (Boat).  The colors are nice, and old, derelict items are often fun to photograph.  I wonder why you included the powerlines and the tower on the left.  Deliberately?  Or would moving to your left and maybe having the boat higher up in the frame have given you a more interesting shot?  Did you try that angle?  Btw, you did go out at the right time, the "golden hours" and your lighting is wonderful :)</td>', 'Yep, you met the challenge here (Boat).  The colors are nice, and old, derelict items are often fun to photograph.  I wonder why you included the powerlines and the tower on the left.  Deliberately?  Or would moving to your left and maybe having the boat higher up in the frame have given you a more interesting shot?  Did you try that angle?  Btw, you did go out at the right time, the "golden hours" and your lighting is wonderful :)', '2003-06-30 22:27:21.000000', NULL, 1),
(343232, 26861, 1041, '<td valign="top">You met the challenge, even though canon and tree would''ve been the first two words to come to mind for me.  B&amp;w / duotone often works well for battlefield / canons / old kind of photos, I''m not sure it works here.  The canons are merging too much into the background for me, but I think with color the sky would''ve probably been too blown out and gray.  A tough choice.  Maybe even come back in different light (if possible).  I do like the composition and framing.</td>', 'You met the challenge, even though canon and tree would''ve been the first two words to come to mind for me.  B&w / duotone often works well for battlefield / canons / old kind of photos, I''m not sure it works here.  The canons are merging too much into the background for me, but I think with color the sky would''ve probably been too blown out and gray.  A tough choice.  Maybe even come back in different light (if possible).  I do like the composition and framing.', '2003-06-30 22:29:31.000000', NULL, 1),
(343242, 26952, 1041, '<td valign="top">What a totally whacky angle ... I love it!  Love that you cut your image in half, the over-saturated sky and those tiny little people scrambling up the sand dune.  It all works perfectly together, plus, you met the challenge.  In my top five this week :)</td>', 'What a totally whacky angle ... I love it!  Love that you cut your image in half, the over-saturated sky and those tiny little people scrambling up the sand dune.  It all works perfectly together, plus, you met the challenge.  In my top five this week :)', '2003-06-30 22:53:35.000000', NULL, 1),
(343244, 26417, 1041, '<td valign="top">Bicurcating: To separate into two parts or branches; fork.  If nothing else, I just learned something new ... had to look up what your title means :)  Met the challenge.  This very much looks like digital art to me, and it doesn''t often happen that that kind of shot appeals to me.  Unfortunately, you fell a bit short of it here, too.  The "thing" on the right that''s branching out, is it a branch?  Judging by the title, this is the subject of your photo, to me, without the title, it''s a little distracting from those glass block windows.  Not sure about the colors, either, sorry ... :(  I guess I just don''t get it.</td>', 'Bicurcating: To separate into two parts or branches; fork.  If nothing else, I just learned something new ... had to look up what your title means :)  Met the challenge.  This very much looks like digital art to me, and it doesn''t often happen that that kind of shot appeals to me.  Unfortunately, you fell a bit short of it here, too.  The "thing" on the right that''s branching out, is it a branch?  Judging by the title, this is the subject of your photo, to me, without the title, it''s a little distracting from those glass block windows.  Not sure about the colors, either, sorry ... :(  I guess I just don''t get it.', '2003-06-30 22:57:14.000000', NULL, 1),
(343246, 26376, 1041, '<td valign="top">LOL ... you got that title from the forums!  Well, you meet the challenge many-fold.  Plus, your image stands out amongst the usual DPC submissions.  Bold, colorful, technically well done.  Love the look on her face, those extravagant glasses plus the sand and sky in the background.  You easily made it into my top 5 this week :)</td>', 'LOL ... you got that title from the forums!  Well, you meet the challenge many-fold.  Plus, your image stands out amongst the usual DPC submissions.  Bold, colorful, technically well done.  Love the look on her face, those extravagant glasses plus the sand and sky in the background.  You easily made it into my top 5 this week :)', '2003-06-30 22:59:00.000000', NULL, 1),
(343247, 26910, 1041, '<td valign="top">Another one of those submissions that are too small for me to really look at and critique.  The max allowable size on DPC is 640x640, it usually helps to take advantage of something at least close to it.  Having said that, you met the challenge, I love those reflections (I''m a sucker for reflections :) and I''d be really interested in seeing a bigger version of this to take in all the details.</td>', 'Another one of those submissions that are too small for me to really look at and critique.  The max allowable size on DPC is 640x640, it usually helps to take advantage of something at least close to it.  Having said that, you met the challenge, I love those reflections (I''m a sucker for reflections :) and I''d be really interested in seeing a bigger version of this to take in all the details.', '2003-06-30 23:00:51.000000', NULL, 1),
(343249, 26938, 1041, '<td valign="top">Challenge is met, and you have an image with potential here.  Great green colors reflected in the water, great reflections, period.  Old tree stumps also often make a good subject.  Here, there are too many other dead branches for my liking, making the image look a bit cluttered.  Plus, it''s not quite focused, or else use of USM would maybe help look this a little sharper.</td>', 'Challenge is met, and you have an image with potential here.  Great green colors reflected in the water, great reflections, period.  Old tree stumps also often make a good subject.  Here, there are too many other dead branches for my liking, making the image look a bit cluttered.  Plus, it''s not quite focused, or else use of USM would maybe help look this a little sharper.', '2003-06-30 23:03:05.000000', NULL, 1),
(343252, 26811, 1041, '<td valign="top">Challenge met.  Beautiful specimen of a rose, good color, and focus.  The background looks somewhat divided with the dark leaves on top and the green cardboard in the lower half.  The shadows from the lighting are a little harsher than I think suits a sensuous rose.</td>', 'Challenge met.  Beautiful specimen of a rose, good color, and focus.  The background looks somewhat divided with the dark leaves on top and the green cardboard in the lower half.  The shadows from the lighting are a little harsher than I think suits a sensuous rose.', '2003-06-30 23:04:44.000000', NULL, 1),
(343254, 26884, 1041, '<td valign="top">Challenge met.  What a wonderful capture of a bug.  I''d be proud to have taken this shot.  Lovely colors, crystal-clear focus and sharpness, and he almost seems to look at me.  The background is nicely green and OOF without any distractions.  The lower end of the bug is a tad OOF but really not noticable much since you have focus and attention-grabbing detail where it matters.  My top 5 this week :)</td>', 'Challenge met.  What a wonderful capture of a bug.  I''d be proud to have taken this shot.  Lovely colors, crystal-clear focus and sharpness, and he almost seems to look at me.  The background is nicely green and OOF without any distractions.  The lower end of the bug is a tad OOF but really not noticable much since you have focus and attention-grabbing detail where it matters.  My top 5 this week :)', '2003-06-30 23:06:14.000000', NULL, 1),
(343258, 26525, 6888, '<td valign="top">focus doesn''t seem very sharp to me</td>', 'focus doesn''t seem very sharp to me', '2003-06-30 23:10:58.000000', NULL, 1),
