(346097, 26376, 1202, '<td valign="top">A wonderful picture to say the least.  Even with your explanitory title I miss seeing a "B" thing as the subject.  If there were more water I would go for beach though.   6</td>', 'A wonderful picture to say the least.  Even with your explanitory title I miss seeing a "B" thing as the subject.  If there were more water I would go for beach though.   6', '2003-07-03 11:48:38.000000', NULL, 1),
(346099, 26851, 3540, '<td valign="top">Like the way the rails frame this shot.  Outstanding color and exposure.  Too bad the water couldn''t be a little calmer.  Very well done -8</td>', 'Like the way the rails frame this shot.  Outstanding color and exposure.  Too bad the water couldn''t be a little calmer.  Very well done -8', '2003-07-03 11:49:41.000000', NULL, 1),
(346101, 26722, 1202, '<td valign="top">This is a well composed landscape, actually very well composed.   I think if it were not a DPC picture I would remove the little birds to clean it up.  8</td>', 'This is a well composed landscape, actually very well composed.   I think if it were not a DPC picture I would remove the little birds to clean it up.  8', '2003-07-03 11:51:08.000000', NULL, 1),
(346105, 26387, 1202, '<td valign="top">I guess this would be called "High Key".  Nicely done and grainy helps in this case.  7</td>', 'I guess this would be called "High Key".  Nicely done and grainy helps in this case.  7', '2003-07-03 11:53:02.000000', NULL, 1),
(346106, 26828, 1202, '<td valign="top">I feel that you cropped this a bit close.  Wonderful subject and well executed shot.  8</td>', 'I feel that you cropped this a bit close.  Wonderful subject and well executed shot.  8', '2003-07-03 11:54:16.000000', NULL, 1),
(346112, 26817, 7291, '<td valign="top">You''re very brave to be getting that close.  I''m getting the "creeps" just looking at this.</td>', 'You''re very brave to be getting that close.  I''m getting the "creeps" just looking at this.', '2003-07-03 11:58:27.000000', NULL, 1),
(346114, 26952, 1202, '<td valign="top">What in the hell are those people doing?  I like the tilt and great sky in this picture.   I wonder what it would be like without the little tiny people?   7</td>', 'What in the hell are those people doing?  I like the tilt and great sky in this picture.   I wonder what it would be like without the little tiny people?   7', '2003-07-03 12:00:31.000000', NULL, 1),
(346119, 26922, 7291, '<td valign="top">I really like the light tone of colors you chose for this.</td>', 'I really like the light tone of colors you chose for this.', '2003-07-03 12:03:24.000000', NULL, 1),
(346120, 26924, 1202, '<td valign="top">What a nice wat to preserve a momento from a great occasion.  I am not sure if I like the bell out of focus, or if it should have been more included.  At least for the challenge, more bell.   For prosperity it is super as is.   8</td>', 'What a nice wat to preserve a momento from a great occasion.  I am not sure if I like the bell out of focus, or if it should have been more included.  At least for the challenge, more bell.   For prosperity it is super as is.   8', '2003-07-03 12:03:49.000000', NULL, 1),
(346125, 26429, 1202, '<td valign="top">A different subject.  I feel the hat is too blown out and the grey-ish background is distracting.   I imagine a picture of this nature being used for advertisement, which means to me that it can''t be flawed.  6</td>', 'A different subject.  I feel the hat is too blown out and the grey-ish background is distracting.   I imagine a picture of this nature being used for advertisement, which means to me that it can''t be flawed.  6', '2003-07-03 12:06:45.000000', NULL, 1),
(346127, 26442, 1202, '<td valign="top">This looks a bit over processed in edit.   The detail of the petals is gone, and the color is quite flat.   You have a nice composition and good background though.  5</td>', 'This looks a bit over processed in edit.   The detail of the petals is gone, and the color is quite flat.   You have a nice composition and good background though.  5', '2003-07-03 12:08:39.000000', NULL, 1),
(346135, 26948, 7291, '<td valign="top">Blue Behr Paint wuold have made a nice thouch, but I''m sure this is what you had at your disposal.  Good lighting.</td>', 'Blue Behr Paint wuold have made a nice thouch, but I''m sure this is what you had at your disposal.  Good lighting.', '2003-07-03 12:15:44.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(346141, 26954, 7291, '<td valign="top">Why does the Suzuki logo look super-imposed on the image?  Looks a little fake.  That''s a crazy move on the bike by the way.</td>', 'Why does the Suzuki logo look super-imposed on the image?  Looks a little fake.  That''s a crazy move on the bike by the way.', '2003-07-03 12:22:48.000000', NULL, 1),
(346144, 26844, 7291, '<td valign="top">Excellent capture!  The yellow is outstanding.  Probably stretching it a little bit to meet the challenge, but then again...so is mine.  =)</td>', 'Excellent capture!  The yellow is outstanding.  Probably stretching it a little bit to meet the challenge, but then again...so is mine.  =)', '2003-07-03 12:25:11.000000', NULL, 1),
(346146, 26825, 7291, '<td valign="top">Excellent job with the lighting!!!</td>', 'Excellent job with the lighting!!!', '2003-07-03 12:26:55.000000', NULL, 1),
(346156, 26947, 7291, '<td valign="top">Excellent portrait.  Just a bit soft around the face though.</td>', 'Excellent portrait.  Just a bit soft around the face though.', '2003-07-03 12:38:37.000000', NULL, 1),
(346166, 26391, 6771, '<td valign="top">Unfortunately this is a very small picture, and hard to judge on.  I really love the colors though.  From this perspective it looks in focus.</td>', 'Unfortunately this is a very small picture, and hard to judge on.  I really love the colors though.  From this perspective it looks in focus.', '2003-07-03 12:52:27.000000', NULL, 1),
(346170, 26525, 6771, '<td valign="top">Great bright colors, but, unfortunately OOF or some kind of blur from motion.  Best to use a timer/release and a tripod for these macros.</td>', 'Great bright colors, but, unfortunately OOF or some kind of blur from motion.  Best to use a timer/release and a tripod for these macros.', '2003-07-03 12:53:42.000000', NULL, 1),
(346174, 26609, 6771, '<td valign="top">I really like the colors in this shot.  Is a bit on the bland side and not "exciting.  Is there a reason behind why you chose this type of crop?</td>', 'I really like the colors in this shot.  Is a bit on the bland side and not "exciting.  Is there a reason behind why you chose this type of crop?', '2003-07-03 12:55:08.000000', NULL, 1),
(346176, 26954, 6771, '<td valign="top">Wider aperture and quicker shutter speed may have helped freeze this one better, which is how I would like to see it...frozen solid, like he stuck that front tire on a dime.  the colors also seem a bit bland and "washed out."</td>', 'Wider aperture and quicker shutter speed may have helped freeze this one better, which is how I would like to see it...frozen solid, like he stuck that front tire on a dime.  the colors also seem a bit bland and "washed out."', '2003-07-03 12:56:39.000000', NULL, 1),
(346177, 26663, 6771, '<td valign="top">For this type of lighting, I really would have liked to seen this back some and maybe off at an angle?  Alot of blown out areas that draw attention more than the eyes do , which should be the emphasis.  How did one pupil end up at about 5mm and the other at 3mm?  (sorry RN coming out.)</td>', 'For this type of lighting, I really would have liked to seen this back some and maybe off at an angle?  Alot of blown out areas that draw attention more than the eyes do , which should be the emphasis.  How did one pupil end up at about 5mm and the other at 3mm?  (sorry RN coming out.)', '2003-07-03 12:59:01.000000', NULL, 1),
(346180, 26878, 6771, '<td valign="top">This would make a great shot for a kitchen.  I think the lighting is a bit too bright.  Would like a touch darker to satureate the colors and make a few more shadows for contrast.</td>', 'This would make a great shot for a kitchen.  I think the lighting is a bit too bright.  Would like a touch darker to satureate the colors and make a few more shadows for contrast.', '2003-07-03 13:00:59.000000', NULL, 1),
(346181, 26866, 6771, '<td valign="top">I like the color touch.  More DOF (and possibly faster shutter speed to freeze the bees) to get all the flowers  on the same focal plane, since they are really highlighted with the desat of the rest of the colors</td>', 'I like the color touch.  More DOF (and possibly faster shutter speed to freeze the bees) to get all the flowers  on the same focal plane, since they are really highlighted with the desat of the rest of the colors', '2003-07-03 13:03:02.000000', NULL, 1),
(346197, 26924, 7291, '<td valign="top">A larger depth of field (larger number) would''ve made more of the text in focus.</td>', 'A larger depth of field (larger number) would''ve made more of the text in focus.', '2003-07-03 13:34:13.000000', NULL, 1),
(346199, 26428, 7291, '<td valign="top">Excellent job.  I especially like the slight cast of light on the person (you?)</td>', 'Excellent job.  I especially like the slight cast of light on the person (you?)', '2003-07-03 13:35:25.000000', NULL, 1),
(346200, 26913, 7291, '<td valign="top">What a stunning picture!!!  Colors are fantastic.</td>', 'What a stunning picture!!!  Colors are fantastic.', '2003-07-03 13:37:22.000000', NULL, 1),
(346201, 26452, 7291, '<td valign="top">My only vote for 10 so far (and I''m than halfway done).  Beautiful picture!</td>', 'My only vote for 10 so far (and I''m than halfway done).  Beautiful picture!', '2003-07-03 13:39:18.000000', NULL, 1),
(346202, 26691, 7291, '<td valign="top">Great choice of background color.  Almost like a rust color.  Contrasts very well with the green.</td>', 'Great choice of background color.  Almost like a rust color.  Contrasts very well with the green.', '2003-07-03 13:40:36.000000', NULL, 1),
(346203, 26525, 806, '<td valign="top">fabulous color, completely outof focus/blurry.</td>', 'fabulous color, completely outof focus/blurry.', '2003-07-03 13:43:03.000000', NULL, 1),
(346204, 26609, 806, '<td valign="top">uninspiring shot.. fits the challenge with the "B''s". Flat lighting, no interest level.  sorry :(</td>', 'uninspiring shot.. fits the challenge with the "B''s". Flat lighting, no interest level.  sorry :(', '2003-07-03 13:43:53.000000', NULL, 1),
(346205, 26910, 806, '<td valign="top">seems interesting, too small to really tell. :(</td>', 'seems interesting, too small to really tell. :(', '2003-07-03 13:44:35.000000', NULL, 1),
(346207, 26706, 7291, '<td valign="top">Nice picture, but a bit of a stretch for the chellenge.</td>', 'Nice picture, but a bit of a stretch for the chellenge.', '2003-07-03 13:48:24.000000', NULL, 1),
(346211, 26169, 7291, '<td valign="top">IS THAT REAL!?!?!</td>', 'IS THAT REAL!?!?!', '2003-07-03 13:51:13.000000', NULL, 1),
(346214, 26731, 7291, '<td valign="top">Insect Porn!!!  LOL, just kidding.  Good capture and choice of crop.</td>', 'Insect Porn!!!  LOL, just kidding.  Good capture and choice of crop.', '2003-07-03 13:53:33.000000', NULL, 1),
(346218, 26442, 6771, '<td valign="top">I do like the rich colors and contrast, but the background is very noisy.  DOF works well, but a touch more on the front flower to make it appear a bit sharper.</td>', 'I do like the rich colors and contrast, but the background is very noisy.  DOF works well, but a touch more on the front flower to make it appear a bit sharper.', '2003-07-03 13:59:39.000000', NULL, 1),
(346223, 26318, 6771, '<td valign="top">Great idea and imaginative.  I think more DOF to bring the front bear more into the same focal plane.  A bit of harsh lighting on the left side of the middle bear and top of the head of the last one</td>', 'Great idea and imaginative.  I think more DOF to bring the front bear more into the same focal plane.  A bit of harsh lighting on the left side of the middle bear and top of the head of the last one', '2003-07-03 14:10:23.000000', NULL, 1),
(346230, 26907, 6771, '<td valign="top">This looks like an awesome place to visit.  Would a lower angle maybe have given a bit more interesting perspective?  Looking up more with the trees a bit larger and then the mountain looming just over the top and through the trees?  There is great color in the foreground, but the contrast and color seems to fade and become more bland the farther back it goes.  Hard thing to fix, but maybe smaller aperture (5.6-8.0) and slightly longer shutter speed?  Worth a shot</td>', 'This looks like an awesome place to visit.  Would a lower angle maybe have given a bit more interesting perspective?  Looking up more with the trees a bit larger and then the mountain looming just over the top and through the trees?  There is great color in the foreground, but the contrast and color seems to fade and become more bland the farther back it goes.  Hard thing to fix, but maybe smaller aperture (5.6-8.0) and slightly longer shutter speed?  Worth a shot', '2003-07-03 14:15:16.000000', NULL, 1),
(346235, 26910, 6771, '<td valign="top">Picture size is too small to make a accurate criticism.  This is a cool idea with the mirror reflections going on and on and upside down and different parts seen .  From the size it is at cannot judge on the focus very well.</td>', 'Picture size is too small to make a accurate criticism.  This is a cool idea with the mirror reflections going on and on and upside down and different parts seen .  From the size it is at cannot judge on the focus very well.', '2003-07-03 14:19:36.000000', NULL, 1),
(346309, 26823, 6597, '<td valign="top">I like the dark background. looks good enougn to eat 8</td>', 'I like the dark background. looks good enougn to eat 8', '2003-07-03 16:52:53.000000', NULL, 1),
(346311, 26816, 6771, '<td valign="top">Good idea.  A little too bright of light/flash that reflects in the glass.  A bit bright in areas like the faces and the pants.  Maybe step]ing back a bit to get the feet included and might rid the flash glare?</td>', 'Good idea.  A little too bright of light/flash that reflects in the glass.  A bit bright in areas like the faces and the pants.  Maybe step]ing back a bit to get the feet included and might rid the flash glare?', '2003-07-03 16:53:13.000000', NULL, 1),
(346313, 26203, 6771, '<td valign="top">Very cute.  Kind of a generic sort of picture, but extremely memorable for those involved.  Colors are a touch flat</td>', 'Very cute.  Kind of a generic sort of picture, but extremely memorable for those involved.  Colors are a touch flat', '2003-07-03 16:54:12.000000', NULL, 1),
(346319, 26938, 6771, '<td valign="top">Interesting choice.  Touch fuzzy.  maybe using landscape mode or closing down the aperture  and increasing the shutter speed.  Like to see a bit more of the reflections</td>', 'Interesting choice.  Touch fuzzy.  maybe using landscape mode or closing down the aperture  and increasing the shutter speed.  Like to see a bit more of the reflections', '2003-07-03 16:55:23.000000', NULL, 1),
(346320, 26274, 6597, '<td valign="top">I like the matching border in this photo. Helps a lot.</td>', 'I like the matching border in this photo. Helps a lot.', '2003-07-03 16:55:49.000000', NULL, 1),
(346322, 26449, 6771, '<td valign="top">Lighting is almost dead on, especially in the back part of the banana.  Love the shadows, but the top of the banana is a bit blown out and too bright.  Nice work with no background artifact.</td>', 'Lighting is almost dead on, especially in the back part of the banana.  Love the shadows, but the top of the banana is a bit blown out and too bright.  Nice work with no background artifact.', '2003-07-03 16:56:28.000000', NULL, 1),
(346324, 26768, 6771, '<td valign="top">I like the hint there.  Creative.  Too contrasty and oversaturated for me.</td>', 'I like the hint there.  Creative.  Too contrasty and oversaturated for me.', '2003-07-03 16:57:26.000000', NULL, 1),
(346326, 26817, 6597, '<td valign="top">You have captured the Bees well. I like the way they glisten, 8</td>', 'You have captured the Bees well. I like the way they glisten, 8', '2003-07-03 16:57:59.000000', NULL, 1),
(346327, 26295, 6771, '<td valign="top">Nice moment.  Wondering what he is saying.  They brothers?  Like to see the colors up a bit, appear a litle flat too me on the grass area.  Maybe a crop into the 2 shoulders up?</td>', 'Nice moment.  Wondering what he is saying.  They brothers?  Like to see the colors up a bit, appear a litle flat too me on the grass area.  Maybe a crop into the 2 shoulders up?', '2003-07-03 16:58:46.000000', NULL, 1),
(346328, 26077, 6597, '<td valign="top">good depth of field.  I like the color 7</td>', 'good depth of field.  I like the color 7', '2003-07-03 16:59:19.000000', NULL, 1),
(346330, 26830, 6597, '<td valign="top">Beautiful color. well done 8</td>', 'Beautiful color. well done 8', '2003-07-03 17:00:09.000000', NULL, 1),
(346332, 26670, 6771, '<td valign="top">Nicde reflections and able to see the bottom of the stream.  Not sure if the wings are just that dark or needed a touch more light on them.  Hard to see any detail (if any).  May be a bit too bright in the left part of the shot.</td>', 'Nicde reflections and able to see the bottom of the stream.  Not sure if the wings are just that dark or needed a touch more light on them.  Hard to see any detail (if any).  May be a bit too bright in the left part of the shot.', '2003-07-03 17:00:36.000000', NULL, 1),
(346334, 26912, 6597, '<td valign="top">a little action is great.</td>', 'a little action is great.', '2003-07-03 17:01:10.000000', NULL, 1),
(346335, 26851, 6771, '<td valign="top">Absolutely spectacular!!  No complaints here A 10!!</td>', 'Absolutely spectacular!!  No complaints here A 10!!', '2003-07-03 17:01:38.000000', NULL, 1),
(346336, 26815, 6771, '<td valign="top">My second highest rating.  Lovely silhouette and colors!!  Like the slight reflections on the waves</td>', 'My second highest rating.  Lovely silhouette and colors!!  Like the slight reflections on the waves', '2003-07-03 17:02:22.000000', NULL, 1),
(346338, 26952, 6771, '<td valign="top">Very awesome!!  Love the perspective and exposure!!  One of my second highest rated!!  Now if I can ever get down there and copy your shot!   (C:</td>', 'Very awesome!!  Love the perspective and exposure!!  One of my second highest rated!!  Now if I can ever get down there and copy your shot!   (C:', '2003-07-03 17:03:16.000000', NULL, 1),
(346339, 26341, 6597, '<td valign="top">good background, the blade adds interest to the banana, good idea 6</td>', 'good background, the blade adds interest to the banana, good idea 6', '2003-07-03 17:03:20.000000', NULL, 1),
(346342, 26251, 6597, '<td valign="top">a little dark but that,s not bad on this photo</td>', 'a little dark but that,s not bad on this photo', '2003-07-03 17:05:34.000000', NULL, 1),
(346343, 26419, 6771, '<td valign="top">Spectacular shot.  The colors and exposure are outstanding.  Great silhouettes</td>', 'Spectacular shot.  The colors and exposure are outstanding.  Great silhouettes', '2003-07-03 17:09:11.000000', NULL, 1),
(346344, 26753, 8643, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2003-07-03 17:09:25.000000', NULL, 1),
(346345, 26817, 6771, '<td valign="top">Bees doing a dance?  This is a great shot.  Those honey makers may be out to get a hold of this shot!</td>', 'Bees doing a dance?  This is a great shot.  Those honey makers may be out to get a hold of this shot!', '2003-07-03 17:10:02.000000', NULL, 1),
(346347, 26631, 6771, '<td valign="top">I love the way this almost looks B&amp;W.  the people sitting in the top left are sneaky but add to it.  Good exposure.  Great job!</td>', 'I love the way this almost looks B&W.  the people sitting in the top left are sneaky but add to it.  Good exposure.  Great job!', '2003-07-03 17:11:25.000000', NULL, 1),
(346353, 26830, 6771, '<td valign="top">Spectacular colors.  Like the "little" boat and its wake out there.  Interesting how you can see the currents and different water movements in the waves.</td>', 'Spectacular colors.  Like the "little" boat and its wake out there.  Interesting how you can see the currents and different water movements in the waves.', '2003-07-03 17:13:03.000000', NULL, 1),
(346365, 26835, 8643, '<td valign="top">Full of atmosphere, brilliant, blue.</td>', 'Full of atmosphere, brilliant, blue.', '2003-07-03 17:18:22.000000', NULL, 1),
(346368, 26952, 6912, '<td valign="top">Wonderful perspective, great idea and something very original!</td>', 'Wonderful perspective, great idea and something very original!', '2003-07-03 17:21:59.000000', NULL, 1),
(346382, 26875, 6912, '<td valign="top">Great idea, look a bit tilted to the right tho, but I like it anyways :-)</td>', 'Great idea, look a bit tilted to the right tho, but I like it anyways :-)', '2003-07-03 17:41:29.000000', NULL, 1),
(346383, 26913, 6912, '<td valign="top">Lovely color combination and the use of the negative space! 9</td>', 'Lovely color combination and the use of the negative space! 9', '2003-07-03 17:43:51.000000', NULL, 1),
(346384, 26951, 6912, '<td valign="top">the picture you have got here has got LOTS of character in it! IMPRESSIVE!</td>', 'the picture you have got here has got LOTS of character in it! IMPRESSIVE!', '2003-07-03 17:46:16.000000', NULL, 1),
(346387, 26855, 4517, '<td valign="top">You`ve  made an excellent photo out of a dull everyday object. 10</td>', 'You`ve  made an excellent photo out of a dull everyday object. 10', '2003-07-03 17:46:56.000000', NULL, 1),
(346389, 26883, 4517, '<td valign="top">Great macro with excellent detail but to me that`s "d" for daisy.</td>', 'Great macro with excellent detail but to me that`s "d" for daisy.', '2003-07-03 17:50:52.000000', NULL, 1),
(346390, 26433, 4517, '<td valign="top">Nice pic that meets the challenge but maybe to much sky.</td>', 'Nice pic that meets the challenge but maybe to much sky.', '2003-07-03 17:52:00.000000', NULL, 1),
(346393, 26638, 6912, '<td valign="top">VIVA SIMPLICITY!!!!! 9 from me! I like your photo very much!!!!!!</td>', 'VIVA SIMPLICITY!!!!! 9 from me! I like your photo very much!!!!!!', '2003-07-03 18:01:50.000000', NULL, 1),
(346435, 26625, 2152, '<td valign="top">I''m not sure what you mean by beauty here...  If you''re calling this beautiful because she''s your child and therefore a beautiful thing, I guess I can see that.  If she''s supposed to be looking at something beautiful and is captivated by it, that''s a possibility, but I can''t see enough in the reflection to be sure.  If, as I suspect, you''re saying this girl is beautiful, well, I can''t really tell.  The sunglasses hide a significant part of her face, the composition isn''t really flattering and as someone who is left to guess at the intentions of this photograph, it seems to me you took a picture of your daughter (sister, granddaughter, whatever) on the beach and picked a word starting with "B" so you could make it fit the challenge.<br/> <br/>You did a good job controlling the exposure, but this shot does not say beauty (in the traditional sense) to me.</td>', 'I''m not sure what you mean by beauty here...  If you''re calling this beautiful because she''s your child and therefore a beautiful thing, I guess I can see that.  If she''s supposed to be looking at something beautiful and is captivated by it, that''s a possibility, but I can''t see enough in the reflection to be sure.  If, as I suspect, you''re saying this girl is beautiful, well, I can''t really tell.  The sunglasses hide a significant part of her face, the composition isn''t really flattering and as someone who is left to guess at the intentions of this photograph, it seems to me you took a picture of your daughter (sister, granddaughter, whatever) on the beach and picked a word starting with "B" so you could make it fit the challenge. You did a good job controlling the exposure, but this shot does not say beauty (in the traditional sense) to me.', '2003-07-03 19:24:19.000000', NULL, 1),
(346437, 26631, 2152, '<td valign="top">Nice shot.  I like the backlighting and how it causes the spray to be in contrast to the rocks behind.  But I''m also thinking it might have been nice to see some more of the rock texture.  Those people could get lost, but hey, you can''t have everything.</td>', 'Nice shot.  I like the backlighting and how it causes the spray to be in contrast to the rocks behind.  But I''m also thinking it might have been nice to see some more of the rock texture.  Those people could get lost, but hey, you can''t have everything.', '2003-07-03 19:24:46.000000', NULL, 1),
(346438, 26910, 2152, '<td valign="top">This looks like a pretty nice shot, but at such a small file size, I can''t really tell...  Good colors and reflections.  But when you resize, set the longest edge to 640 pixels.</td>', 'This looks like a pretty nice shot, but at such a small file size, I can''t really tell...  Good colors and reflections.  But when you resize, set the longest edge to 640 pixels.', '2003-07-03 19:26:52.000000', NULL, 1),
(346469, 26742, 6771, '<td valign="top">I really like the angle on this macro.  Got right up in there.  I feel it is lacking a little DOF.  I am seeing great detail in the lower petals and then when it get up into the hair(ier) looking petals it seems to fuzz out some, as with the bee.  For this type of shot I would like it to be crisp and sharp all over the flower and bee</td>', 'I really like the angle on this macro.  Got right up in there.  I feel it is lacking a little DOF.  I am seeing great detail in the lower petals and then when it get up into the hair(ier) looking petals it seems to fuzz out some, as with the bee.  For this type of shot I would like it to be crisp and sharp all over the flower and bee', '2003-07-03 20:34:44.000000', NULL, 1),
(346472, 26812, 6771, '<td valign="top">The fisherman fall overboard?  I love the water and reflection leading up to the boat, but then when it gets there it seems that the focus isn''t as tight as it could be.  This is composed very well and technique is good, just that first point sticks with me.</td>', 'The fisherman fall overboard?  I love the water and reflection leading up to the boat, but then when it gets there it seems that the focus isn''t as tight as it could be.  This is composed very well and technique is good, just that first point sticks with me.', '2003-07-03 20:37:05.000000', NULL, 1),
(346473, 26651, 6771, '<td valign="top">How long did you have to wait for this one?  I really like the two different colors and how they split the photo.  It seems that the nests have a bit too much light from (the flash?) on them and it takes a little away from the great textures and contrasts in it.</td>', 'How long did you have to wait for this one?  I really like the two different colors and how they split the photo.  It seems that the nests have a bit too much light from (the flash?) on them and it takes a little away from the great textures and contrasts in it.', '2003-07-03 20:38:53.000000', NULL, 1),
(346477, 26341, 6771, '<td valign="top">Great perspective and DOF.  Can see a fingerprint on the blade even.  The two things that brought this photo down some in my opinion is that the yellow may be over saturated a bit, and it makes the top side overbearing.  And the shadow is a bit distracting for some reason.  The way it shows real well on the bottom of the banana is geat and the little bit that shows another section a bit higher, but the way it is cast on the mat distracts me for some reason.  Wish I could figure out why</td>', 'Great perspective and DOF.  Can see a fingerprint on the blade even.  The two things that brought this photo down some in my opinion is that the yellow may be over saturated a bit, and it makes the top side overbearing.  And the shadow is a bit distracting for some reason.  The way it shows real well on the bottom of the banana is geat and the little bit that shows another section a bit higher, but the way it is cast on the mat distracts me for some reason.  Wish I could figure out why', '2003-07-03 20:42:51.000000', NULL, 1),
(346481, 26844, 6771, '<td valign="top">I really like this shot.  Good colors and tones.  the DOF could be a bit deeper to bring the boy on the left into sharper focus, since I feel that he is the one that is the "boyfriend."    But a bit of motion blur may seem to be the problem.  Then a faster shutter speed would help</td>', 'I really like this shot.  Good colors and tones.  the DOF could be a bit deeper to bring the boy on the left into sharper focus, since I feel that he is the one that is the "boyfriend."    But a bit of motion blur may seem to be the problem.  Then a faster shutter speed would help', '2003-07-03 20:45:03.000000', NULL, 1),
