(346944, 26948, 7857, '<td valign="top">Nice subject, and with the brush on the top theres no question of not meeting the challenge. A different BG colour could look nicer here... Say a board painted with some of the paint to they match but aren''t as harsh together as the white can and white BG... or perhaps a slightly darker version of the paint colour, like a more terracotta. Good luck with it.</td>', 'Nice subject, and with the brush on the top theres no question of not meeting the challenge. A different BG colour could look nicer here... Say a board painted with some of the paint to they match but aren''t as harsh together as the white can and white BG... or perhaps a slightly darker version of the paint colour, like a more terracotta. Good luck with it.', '2003-07-04 12:16:14.000000', NULL, 1),
(346994, 26884, 9690, '<td valign="top">Can''t get any better than this... very sharp, great colors... good job</td>', 'Can''t get any better than this... very sharp, great colors... good job', '2003-07-04 13:29:19.000000', NULL, 1),
(347002, 26844, 772, '<td valign="top">This is beautiful work :)  ..my favorite of the week... = 10</td>', 'This is beautiful work :)  ..my favorite of the week... = 10', '2003-07-04 13:56:19.000000', NULL, 1),
(347004, 26450, 6597, '<td valign="top">Nice color  combination good focus   7</td>', 'Nice color  combination good focus   7', '2003-07-04 14:06:39.000000', NULL, 1),
(347011, 26836, 6504, '<td valign="top">Magnificent.  Beautiful colors, clarity, composition.  And very clever title!<br/></td>', 'Magnificent.  Beautiful colors, clarity, composition.  And very clever title!', '2003-07-04 14:31:14.000000', NULL, 1),
(347012, 26855, 6504, '<td valign="top">Very beautifully done.  Best picture I have ever seen of a tooth brush.  You are the winner.   10  The colors, composition, all of it is perfect.  Crest Toothpaste people should contact you.</td>', 'Very beautifully done.  Best picture I have ever seen of a tooth brush.  You are the winner.   10  The colors, composition, all of it is perfect.  Crest Toothpaste people should contact you.', '2003-07-04 14:32:57.000000', NULL, 1),
(347013, 26953, 6504, '<td valign="top">wOW!!  The colors are great and the expression on the bird is perfect.  As if "So you want a picture, eh?"  The clarity of the feathers is excellent.  Blurred background perfect.  All around very very good.</td>', 'wOW!!  The colors are great and the expression on the bird is perfect.  As if "So you want a picture, eh?"  The clarity of the feathers is excellent.  Blurred background perfect.  All around very very good.', '2003-07-04 14:36:26.000000', NULL, 1),
(347014, 26834, 6504, '<td valign="top">Gee!  How did you come across this little guy?  What a perfect picture.  The sun falling on him is so good.  I like the way he''s looking straight on.  You have a very good picture here.</td>', 'Gee!  How did you come across this little guy?  What a perfect picture.  The sun falling on him is so good.  I like the way he''s looking straight on.  You have a very good picture here.', '2003-07-04 14:37:43.000000', NULL, 1),
(347015, 26884, 6504, '<td valign="top">My goodness, look at those eyes!!  What great clarity and color .  He is scary!  How in the world did you get so close to it?  You can even see drops of water on himl  Did you spray him -hahah.  If not the winner, close to it.</td>', 'My goodness, look at those eyes!!  What great clarity and color .  He is scary!  How in the world did you get so close to it?  You can even see drops of water on himl  Did you spray him -hahah.  If not the winner, close to it.', '2003-07-04 14:39:32.000000', NULL, 1),
(347016, 26823, 6504, '<td valign="top">I have a hamburger restaurant, so of course this one is my favorite.  You have done an excellent job of photographing this.  Very appealing and appetizing.  The colored plate competes just a tiny bit with the burger, but so what.  It''s a great pictuare.</td>', 'I have a hamburger restaurant, so of course this one is my favorite.  You have done an excellent job of photographing this.  Very appealing and appetizing.  The colored plate competes just a tiny bit with the burger, but so what.  It''s a great pictuare.', '2003-07-04 14:41:30.000000', NULL, 1),
(347017, 26691, 6504, '<td valign="top">The colors are wonderful, very oriental.  And the compostion is perfect. Very good photograpy.  This is something that should be framed.</td>', 'The colors are wonderful, very oriental.  And the compostion is perfect. Very good photograpy.  This is something that should be framed.', '2003-07-04 14:42:43.000000', NULL, 1),
(347019, 26888, 6504, '<td valign="top">Hahahah  now that''s what I like, a little humour.  You have a good picture here, the colors are good.  But most of all it is very creative.</td>', 'Hahahah  now that''s what I like, a little humour.  You have a good picture here, the colors are good.  But most of all it is very creative.', '2003-07-04 14:44:05.000000', NULL, 1),
(347020, 26251, 6504, '<td valign="top">I thinkthis is very very good.  I like the colors a lot and the way the roof is hightligted.  It has a sentimental feel to it.  Look at the color of the grass in contrast to the sky.  Excellent.<br/></td>', 'I thinkthis is very very good.  I like the colors a lot and the way the roof is hightligted.  It has a sentimental feel to it.  Look at the color of the grass in contrast to the sky.  Excellent.', '2003-07-04 14:45:29.000000', NULL, 1),
(347022, 26912, 6504, '<td valign="top">Good old fashioned barber shop.  A Beauty.  Would look good in sepia, too, but that would ruin the title.</td>', 'Good old fashioned barber shop.  A Beauty.  Would look good in sepia, too, but that would ruin the title.', '2003-07-04 14:47:03.000000', NULL, 1),
(347023, 26844, 6504, '<td valign="top">This is a clever and beautiful pictute.  The yellow touches against the dark skin. Beautiful.  A little more clarity and it would be the winner.</td>', 'This is a clever and beautiful pictute.  The yellow touches against the dark skin. Beautiful.  A little more clarity and it would be the winner.', '2003-07-04 14:48:37.000000', NULL, 1),
(347024, 26206, 6504, '<td valign="top">What a great picture.   I think this is one of the more creative shots of a flower that I have seen.  It''s beautiful!  I like the texture of the flower in the foreground.  All I can say is - Excellent</td>', 'What a great picture.   I think this is one of the more creative shots of a flower that I have seen.  It''s beautiful!  I like the texture of the flower in the foreground.  All I can say is - Excellent', '2003-07-04 14:50:20.000000', NULL, 1),
(347033, 26442, 6597, '<td valign="top">Very good colors 8</td>', 'Very good colors 8', '2003-07-04 15:17:21.000000', NULL, 1),
(347034, 26851, 6597, '<td valign="top">good composition</td>', 'good composition', '2003-07-04 15:18:15.000000', NULL, 1),
(347053, 26413, 6900, '<td valign="top">Excellent lighting.  Nice colors, too.</td>', 'Excellent lighting.  Nice colors, too.', '2003-07-04 16:00:03.000000', NULL, 1),
(347061, 26638, 6900, '<td valign="top">Excellent focus, lighting is a bit harsh.</td>', 'Excellent focus, lighting is a bit harsh.', '2003-07-04 16:05:16.000000', NULL, 1),
(347063, 26818, 6900, '<td valign="top">Ugly border, decent subject and lighting.  I wish the focus gave more blur, but it''s hard to do digitally (maybe use a telephoto lens?).  Ugly bord... oh wait, I said that. :)  7</td>', 'Ugly border, decent subject and lighting.  I wish the focus gave more blur, but it''s hard to do digitally (maybe use a telephoto lens?).  Ugly bord... oh wait, I said that. :)  7', '2003-07-04 16:06:17.000000', NULL, 1),
(347064, 26813, 7758, '<td valign="top">Great shot, I would like to see this in colour.... I would have thought that perhaps this would look better in colour. It has a nice feel to it but just seems to be lacking something in my opinion.... just wondered if it was the lack of colour. Having said that perhaps an increase in the contrast might help too..... not trying to be negative, I think this has quite a good depth to it.... just needs that little something to make it jump off the page. Good Luck, Todd. 8</td>', 'Great shot, I would like to see this in colour.... I would have thought that perhaps this would look better in colour. It has a nice feel to it but just seems to be lacking something in my opinion.... just wondered if it was the lack of colour. Having said that perhaps an increase in the contrast might help too..... not trying to be negative, I think this has quite a good depth to it.... just needs that little something to make it jump off the page. Good Luck, Todd. 8', '2003-07-04 16:06:20.000000', NULL, 1),
(347066, 26341, 6900, '<td valign="top">Unique idea.  9</td>', 'Unique idea.  9', '2003-07-04 16:06:53.000000', NULL, 1),
(347068, 26851, 6900, '<td valign="top">Nice framing, could be a bit much.  Great view of the city!</td>', 'Nice framing, could be a bit much.  Great view of the city!', '2003-07-04 16:07:20.000000', NULL, 1),
(347071, 26525, 6900, '<td valign="top">B is for blurry, that''s good enough for me.  I like the subject, don''t like the grain or the focus.</td>', 'B is for blurry, that''s good enough for me.  I like the subject, don''t like the grain or the focus.', '2003-07-04 16:08:16.000000', NULL, 1),
(347072, 26670, 7758, '<td valign="top">cool shot, not wrapped in the crappy stuff down the right under the leaf, but overall it''s quite good. The black wings look almost cut out or something. Well done. Todd.</td>', 'cool shot, not wrapped in the crappy stuff down the right under the leaf, but overall it''s quite good. The black wings look almost cut out or something. Well done. Todd.', '2003-07-04 16:08:31.000000', NULL, 1),
(347074, 26616, 6900, '<td valign="top">I think your border is technically not a border.  It doesn''t work for this picture, either.  I like the subject and the composition is wonderful.  The colors are great and the blur/focus/dof works well.  I would have flipped this picture around completely.   Gone left to right with it.  More natural flow.  Good luck. 9 (-1 for border issues)</td>', 'I think your border is technically not a border.  It doesn''t work for this picture, either.  I like the subject and the composition is wonderful.  The colors are great and the blur/focus/dof works well.  I would have flipped this picture around completely.   Gone left to right with it.  More natural flow.  Good luck. 9 (-1 for border issues)', '2003-07-04 16:09:50.000000', NULL, 1),
(347075, 26391, 6900, '<td valign="top">too small - good color.</td>', 'too small - good color.', '2003-07-04 16:10:26.000000', NULL, 1),
(347078, 26428, 7758, '<td valign="top">This is well done. Love the way you have picked up the person in the background, really gives the photo some impact. Should do fairly well in this challenge for both originality and impact. Good Luck, Todd.</td>', 'This is well done. Love the way you have picked up the person in the background, really gives the photo some impact. Should do fairly well in this challenge for both originality and impact. Good Luck, Todd.', '2003-07-04 16:11:36.000000', NULL, 1),
(347079, 26706, 6900, '<td valign="top">Reminds me of gigi''s ribbon winner.  Here the sun blew out too much of the ground.  Tones are a little light, too.</td>', 'Reminds me of gigi''s ribbon winner.  Here the sun blew out too much of the ground.  Tones are a little light, too.', '2003-07-04 16:11:47.000000', NULL, 1),
(347081, 26449, 6900, '<td valign="top">border cuts off banana= silly.  banana looks white and overexposed.</td>', 'border cuts off banana= silly.  banana looks white and overexposed.', '2003-07-04 16:12:24.000000', NULL, 1),
(347084, 26844, 6900, '<td valign="top">Excellent shot!  One of my favorites.  10</td>', 'Excellent shot!  One of my favorites.  10', '2003-07-04 16:13:52.000000', NULL, 1),
(347086, 26930, 6900, '<td valign="top">Gee I wonder who this is. lol</td>', 'Gee I wonder who this is. lol', '2003-07-04 16:14:13.000000', NULL, 1),
(347087, 26910, 6900, '<td valign="top">Too small.  Pixels, GIV PLS.</td>', 'Too small.  Pixels, GIV PLS.', '2003-07-04 16:15:30.000000', NULL, 1),
(347088, 26844, 7711, '<td valign="top">love it. The boy''s face is priceless, as is his "disaffected" little gf. what a capture. Ideally, a greater DOF, but I don''t care, not every great picture is technically flawless. 10.</td>', 'love it. The boy''s face is priceless, as is his "disaffected" little gf. what a capture. Ideally, a greater DOF, but I don''t care, not every great picture is technically flawless. 10.', '2003-07-04 16:15:50.000000', NULL, 1),
(347089, 26947, 6900, '<td valign="top">Neat Image?  It doesn''t work on people''s skin- makes it look plasticy.   Good shot, excellent DoF, but the noise reduction hurt this shot.  8</td>', 'Neat Image?  It doesn''t work on people''s skin- makes it look plasticy.   Good shot, excellent DoF, but the noise reduction hurt this shot.  8', '2003-07-04 16:16:57.000000', NULL, 1),
(347090, 26387, 6900, '<td valign="top">out of focus and grainy.</td>', 'out of focus and grainy.', '2003-07-04 16:17:52.000000', NULL, 1),
(347091, 26825, 6900, '<td valign="top">I wish the glass had fewer markups..but it''s a good picture - I love backlighting.</td>', 'I wish the glass had fewer markups..but it''s a good picture - I love backlighting.', '2003-07-04 16:18:19.000000', NULL, 1),
(347092, 26731, 6900, '<td valign="top">ROCK ON!!!!!!!!!</td>', 'ROCK ON!!!!!!!!!', '2003-07-04 16:19:03.000000', NULL, 1),
(347094, 26814, 6900, '<td valign="top">Great toning/color.  IR?  IR has an interesting look.</td>', 'Great toning/color.  IR?  IR has an interesting look.', '2003-07-04 16:19:24.000000', NULL, 1),
(347101, 26832, 6900, '<td valign="top">OMG how FRICKING CUTE!!!!!!!!!  Yes, I get the picture.  I wonder how many will not see it.  *rolls eyes*  Good color, cool blue background, what a unique, beautiful shot.</td>', 'OMG how FRICKING CUTE!!!!!!!!!  Yes, I get the picture.  I wonder how many will not see it.  *rolls eyes*  Good color, cool blue background, what a unique, beautiful shot.', '2003-07-04 16:33:37.000000', NULL, 1),
(347107, 26289, 6900, '<td valign="top">Should win. 10  Excellent high key.</td>', 'Should win. 10  Excellent high key.', '2003-07-04 16:41:16.000000', NULL, 1),
(347108, 26828, 6900, '<td valign="top">Border doesn''t work here.  Nice try anyways.  Good light and good pic - eyes are a bit dark but quite a capture.</td>', 'Border doesn''t work here.  Nice try anyways.  Good light and good pic - eyes are a bit dark but quite a capture.', '2003-07-04 16:44:06.000000', NULL, 1),
(347109, 26873, 6900, '<td valign="top">Great lighting - wish there was a bottom to the glass, though.</td>', 'Great lighting - wish there was a bottom to the glass, though.', '2003-07-04 16:44:21.000000', NULL, 1),
(347112, 26739, 6900, '<td valign="top">Now imagine if most of the sky was cropped and the child was a bit more prominent in the photo.  :)  Get your subject to fill your frame.</td>', 'Now imagine if most of the sky was cropped and the child was a bit more prominent in the photo.  :)  Get your subject to fill your frame.', '2003-07-04 16:46:07.000000', NULL, 1),
(347115, 26835, 5112, '<td valign="top">Ah, Montreal!</td>', 'Ah, Montreal!', '2003-07-04 16:52:27.000000', NULL, 1),
(347126, 26839, 9849, '<td valign="top">Nice shot</td>', 'Nice shot', '2003-07-04 17:31:23.000000', NULL, 1),
(347127, 26912, 3306, '<td valign="top">Nice candid shot. I would have like to see you crop the picture in on the boy and the barber on the left. They both have great expressions.</td>', 'Nice candid shot. I would have like to see you crop the picture in on the boy and the barber on the left. They both have great expressions.', '2003-07-04 17:37:34.000000', NULL, 1),
(347159, 26088, 3087, '<td valign="top">What an absolutely excellent use of shallow DOF! I really like the way the focus settles on the cork, with it''s printed designs, and the rim of the bottle. The sharply angled viewpoint also makes the image striking - reducing a familiar object to a somewhat more unfamiliar shape. Do you have any outtakes with the cork text rotated further into the image? I''m curious as to whether I''d like that better or not than your chosen orientation. I''m not voting this one but this is one of my favourites from this challenge.</td>', 'What an absolutely excellent use of shallow DOF! I really like the way the focus settles on the cork, with it''s printed designs, and the rim of the bottle. The sharply angled viewpoint also makes the image striking - reducing a familiar object to a somewhat more unfamiliar shape. Do you have any outtakes with the cork text rotated further into the image? I''m curious as to whether I''d like that better or not than your chosen orientation. I''m not voting this one but this is one of my favourites from this challenge.', '2003-07-04 18:38:11.000000', NULL, 1),
(347166, 26851, 3087, '<td valign="top">A beautiful image, worthy of being on a greetings card or one of the better postcards. I like the use of the rails to frame and the wonderful colours of the sky reflected in the water. I also like the feeling of distance - as though one is separated from the hustle and bustle and noise of the city itself.</td>', 'A beautiful image, worthy of being on a greetings card or one of the better postcards. I like the use of the rails to frame and the wonderful colours of the sky reflected in the water. I also like the feeling of distance - as though one is separated from the hustle and bustle and noise of the city itself.', '2003-07-04 18:42:04.000000', NULL, 1),
(347170, 26753, 3087, '<td valign="top">I really like this - I would never have thought of low DOF for bubbles and yet it makes such a great abstract where one can really focus on the shapes and colours and light rather than solely on what the subject actually is.</td>', 'I really like this - I would never have thought of low DOF for bubbles and yet it makes such a great abstract where one can really focus on the shapes and colours and light rather than solely on what the subject actually is.', '2003-07-04 18:43:11.000000', NULL, 1),
(347171, 26950, 3087, '<td valign="top">Very unusual and strangely interesting. Love the texture. I would prefer no dark shadow at top right - I think this would make the human silhouette stronger.</td>', 'Very unusual and strangely interesting. Love the texture. I would prefer no dark shadow at top right - I think this would make the human silhouette stronger.', '2003-07-04 18:44:54.000000', NULL, 1),
(347173, 26822, 3087, '<td valign="top">Excellently done and I love the choice to go for black and white. The soft sweeping horizontal lines of the background really contrast with the stubbled texture of the man''s skin.  I want to pop that bubble with my fingernail! Strong composition and good confident cropping. I like it!</td>', 'Excellently done and I love the choice to go for black and white. The soft sweeping horizontal lines of the background really contrast with the stubbled texture of the man''s skin.  I want to pop that bubble with my fingernail! Strong composition and good confident cropping. I like it!', '2003-07-04 18:48:43.000000', NULL, 1),
(347174, 26929, 3087, '<td valign="top">Oooh scary. There are some really superb examples of shallow DOF in this challenge - this is another for me. Great reflection highlights in the eye and I like the duller reflective aspect of some of the scales.</td>', 'Oooh scary. There are some really superb examples of shallow DOF in this challenge - this is another for me. Great reflection highlights in the eye and I like the duller reflective aspect of some of the scales.', '2003-07-04 18:49:54.000000', NULL, 1),
(347176, 26854, 3087, '<td valign="top">Great colours (well chosen background) and I love the close crop and composition. I think this is very simple but very strong.</td>', 'Great colours (well chosen background) and I love the close crop and composition. I think this is very simple but very strong.', '2003-07-04 18:51:10.000000', NULL, 1),
(347178, 26844, 3087, '<td valign="top">This pulls me in the more I look at it - a beautiful candid shot. I think I''d prefer for all the four children to be sharply in focus, especially the grinning mischief maker with the flower. This shot is very powerful for me.</td>', 'This pulls me in the more I look at it - a beautiful candid shot. I think I''d prefer for all the four children to be sharply in focus, especially the grinning mischief maker with the flower. This shot is very powerful for me.', '2003-07-04 18:53:08.000000', NULL, 1),
(347180, 26947, 3087, '<td valign="top">A lovely portrait and works excellently in black and white - the pattern of his T-shirt really helps in that. Love the light in his hair and the background works well for me. Focus feels a little soft on his face for me but I know many people prefer that for portraits - I tend not to myself.</td>', 'A lovely portrait and works excellently in black and white - the pattern of his T-shirt really helps in that. Love the light in his hair and the background works well for me. Focus feels a little soft on his face for me but I know many people prefer that for portraits - I tend not to myself.', '2003-07-04 18:54:53.000000', NULL, 1),
(347191, 26855, 3087, '<td valign="top">What I like about this: The colour of water in the glass and the way it matches the colour of the toothbrush handle. The highlight in the toothpaste gel. The reflection of the brush itself. The light and shadow in the area of the bottom of the glass.<br/>What I don''t like: That I can see smear marks on the surface which kind of distort the reflection of the head of the toothbrush - I appreciate it may be deliberate. The composition - it doesn''t quite feel balanced to me though it''s reasonably strong - I personally would crop just a small touch tighter at the bottom and would like to see the glass extend higher at the top, so crop less there, perhaps.</td>', 'What I like about this: The colour of water in the glass and the way it matches the colour of the toothbrush handle. The highlight in the toothpaste gel. The reflection of the brush itself. The light and shadow in the area of the bottom of the glass.What I don''t like: That I can see smear marks on the surface which kind of distort the reflection of the head of the toothbrush - I appreciate it may be deliberate. The composition - it doesn''t quite feel balanced to me though it''s reasonably strong - I personally would crop just a small touch tighter at the bottom and would like to see the glass extend higher at the top, so crop less there, perhaps.', '2003-07-04 19:07:53.000000', NULL, 1),
(347196, 26442, 3087, '<td valign="top">What strong colour! Well selected background. Angle feels a little too elevated to me though I appreciate that''s what allows us to see the central circle of the flowers. I think I''d like DOF to be even shallower so that the second flower were even further out of focus. Nice composition, cropped a little tight at the lower edge (the flower feels too close to edge of frame there for me).</td>', 'What strong colour! Well selected background. Angle feels a little too elevated to me though I appreciate that''s what allows us to see the central circle of the flowers. I think I''d like DOF to be even shallower so that the second flower were even further out of focus. Nice composition, cropped a little tight at the lower edge (the flower feels too close to edge of frame there for me).', '2003-07-04 19:14:39.000000', NULL, 1),
(347199, 26884, 3087, '<td valign="top">Oh my goodness! That''s scary! The colours of the bug are captured so vividly and the vivid green of the background works well with that. I like the placement of the stem very much - on a slight angle and to the side. I find the crop just a wee bit too tight at the bottom edge - I think there needs to be more room between bottom tip of bug and edge of frame.</td>', 'Oh my goodness! That''s scary! The colours of the bug are captured so vividly and the vivid green of the background works well with that. I like the placement of the stem very much - on a slight angle and to the side. I find the crop just a wee bit too tight at the bottom edge - I think there needs to be more room between bottom tip of bug and edge of frame.', '2003-07-04 19:16:28.000000', NULL, 1),
(347202, 26930, 3087, '<td valign="top">This has a strong composition for me - the balance between grass and sky and the angle and leading line of the bridge itself. That said, there isn''t a really appealing focus point for me - the bridge is a strong architectural feature but doesn''t keep my interest. I am finding the sky quite bright - especially around that cloud at top left. I''m also seeing very stepped (zig-zagged) line along the lower edge of the foreground of the bridge. I like the unusual viewpoint and the composition but this image doesn''t have a visual hook for me.</td>', 'This has a strong composition for me - the balance between grass and sky and the angle and leading line of the bridge itself. That said, there isn''t a really appealing focus point for me - the bridge is a strong architectural feature but doesn''t keep my interest. I am finding the sky quite bright - especially around that cloud at top left. I''m also seeing very stepped (zig-zagged) line along the lower edge of the foreground of the bridge. I like the unusual viewpoint and the composition but this image doesn''t have a visual hook for me.', '2003-07-04 19:23:22.000000', NULL, 1),
(347224, 26875, 8637, '<td valign="top">I really liked this, beautiful suite of colors and great idea.  thanks</td>', 'I really liked this, beautiful suite of colors and great idea.  thanks', '2003-07-04 20:07:50.000000', NULL, 1),
(347225, 26394, 8637, '<td valign="top">One of my favorites...the tiny hairs along the stem really set this one off and bamboo was fairly original.  thanks</td>', 'One of my favorites...the tiny hairs along the stem really set this one off and bamboo was fairly original.  thanks', '2003-07-04 20:08:38.000000', NULL, 1),
(347226, 26910, 8637, '<td valign="top">Nice design and excellent photography.  One of the better ones.  thanks</td>', 'Nice design and excellent photography.  One of the better ones.  thanks', '2003-07-04 20:09:40.000000', NULL, 1),
(347227, 26753, 8637, '<td valign="top">Thought about doing this too, but don''t believe I could have captured as well as you did.  Thanks</td>', 'Thought about doing this too, but don''t believe I could have captured as well as you did.  Thanks', '2003-07-04 20:10:11.000000', NULL, 1),
(347229, 26825, 8637, '<td valign="top">Oh yeahh!  Nice shot and beuatiful design.  Wonder if you tried other illumination to bring out more of the blue as well?  Nice work.  thanks</td>', 'Oh yeahh!  Nice shot and beuatiful design.  Wonder if you tried other illumination to bring out more of the blue as well?  Nice work.  thanks', '2003-07-04 20:11:15.000000', NULL, 1),
(347233, 26924, 8637, '<td valign="top">Nice idea but lot of focus problems...better DOF would have helped greatly.  thanks</td>', 'Nice idea but lot of focus problems...better DOF would have helped greatly.  thanks', '2003-07-04 20:15:03.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(347235, 26844, 8637, '<td valign="top">Nice shot but seemed a stretch for the B competition.</td>', 'Nice shot but seemed a stretch for the B competition.', '2003-07-04 20:15:47.000000', NULL, 1),
(347236, 26948, 8637, '<td valign="top">Long stretch to get across the "B" in this one...also the lighting on the left seems to wash out pretty bad.</td>', 'Long stretch to get across the "B" in this one...also the lighting on the left seems to wash out pretty bad.', '2003-07-04 20:16:42.000000', NULL, 1),
